    getParticipant: wrapPublicHandler(async (request, response) => {
      const participant = await service.getParticipant(getPathParameter(request, 'participantId'));

      if (!participant) {
        sendNotFound(response, 'Participant');
        return;
      }

      response.status(200).json({
        data: participant,
