      command: 'SELECT',
      oid: 0,
      fields: [],
    });
    const repository = createPublicEventRepository({ query } as unknown as QueryExecutor);

    const page = await repository.listAcceptedFixtureEvents({
      fixtureId: '100',
      inningsId: '200',
      competitorId: '20',
      participantId: '30',
      overNumber: 4,
      wicketKind: 'caught',
      after: {
        inningsOrdinal: 0,
        sequenceNumber: 1,
        eventId: '500',
      },
      limit: 2,
    });

